sealed class Etat {}

class Chargement extends Etat {}

class Pret extends Etat {
  Pret(this.nom);
  final String nom;
}

String texte(Etat etat) => switch (etat) {
  Chargement() => 'Patientez...',
  Pret(:final nom) => 'Bonjour, $nom',
};

(int, String) profil() => (7, 'Merlin');

void main() {
  print(texte(Chargement()));
  print(texte(Pret('Viviane')));

  final (niveau, nom) = profil();
  print('$nom : $niveau');
}

