class CompteurControleur extends Notifier<int> {
  @override
  int build() => 0;

  void incrementer() => state++;
}

final compteurProvider = NotifierProvider<CompteurControleur, int>(
  CompteurControleur.new,
);

class EcranCompteur extends ConsumerWidget {
  const EcranCompteur({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final valeur = ref.watch(compteurProvider);

    return FilledButton(
      onPressed: () => ref.read(compteurProvider.notifier).incrementer(),
      child: Text('$valeur'),
    );
  }
}

void main() {
  runApp(const ProviderScope(child: MaterialApp(home: EcranCompteur())));
}

