import 'package:flutter/services.dart';

const _canal = MethodChannel('com.exemple.druide/batterie');

Future<int?> niveauBatterie() async {
  try {
    return await _canal.invokeMethod<int>('niveau');
  } on PlatformException catch (erreur) {
    return Future.error('Batterie illisible : ${erreur.message}');
  } on MissingPluginException {
    return null;
  }
}

class MainActivity : FlutterActivity() {
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)

        MethodChannel(
            flutterEngine.dartExecutor.binaryMessenger,
            "com.exemple.druide/batterie",
        ).setMethodCallHandler { appel, resultat ->
            if (appel.method == "niveau") {
                val gestionnaire = getSystemService(Context.BATTERY_SERVICE) as BatteryManager
                val niveau = gestionnaire.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)
                if (niveau >= 0) {
                    resultat.success(niveau)
                } else {
                    resultat.error("INDISPONIBLE", "Niveau inconnu", null)
                }
            } else {
                resultat.notImplemented()
            }
        }
    }
}

